import { expect, expectStatus, test, type Document } from "../../fixtures";

// One journey across two roles (member uploads and submits, reviewer reads the queue), so it is
// a single test per PW-10. The W-9 bodies are built inline because the factory only takes
// sample files, and the replacement must carry a different legal name.
test.describe("vendor lifecycle", () => {
  test(
    "a re-uploaded document is the one that gets reviewed",
    { tag: "@LIF-01" },
    async ({ apiAs, factory }) => {
      // Arrange
      const member = await apiAs("member");
      const reviewer = await apiAs("reviewer");
      const vendor = await factory.vendor({ as: "member" });
      const insurance = await factory.upload(vendor.id, "insurance_certificate", undefined, "member");
      const contract = await factory.upload(vendor.id, "contract", undefined, "member");
      const w9Upload = (name: string, legalName: string) =>
        member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind: "w9",
            file: {
              name,
              mimeType: "text/plain",
              buffer: Buffer.from(`Legal Name: ${legalName}\nTax ID: 84-2219067\nBusiness Type: LLC\n`),
            },
          },
        });
      const allExtracted = (count: number) =>
        expect.poll(
          async () => {
            const docs = await expectStatus<Document[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
            return docs.map((d) => d.status);
          },
          { message: `${count} documents extracted`, timeout: 30_000 },
        );
      await allExtracted(2).toEqual(["extracted", "extracted"]);

      const first = await expectStatus<Document>(await w9Upload("w9-first.txt", "First Name LLC"), 201);
      await allExtracted(3).toEqual(["extracted", "extracted", "extracted"]);
      const second = await expectStatus<Document>(await w9Upload("w9-second.txt", "Second Name LLC"), 201);
      await allExtracted(4).toEqual(["extracted", "extracted", "extracted", "extracted"]);

      // Act
      await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
      const queue = await expectStatus<
        { vendor_id: string; extractions: { kind: string; fields: Record<string, { value: string | null }> }[] }[]
      >(await reviewer.get("/api/review-queue"), 200);
      const documents = await expectStatus<Document[]>(
        await member.get(`/api/vendors/${vendor.id}/documents`),
        200,
      );

      // Assert
      const item = queue.find((i) => i.vendor_id === vendor.id);
      expect(item, "the submitted vendor is in the review queue").toBeDefined();
      const w9 = item?.extractions.find((e) => e.kind === "w9");
      expect(w9?.fields.legal_name.value).toBe("Second Name LLC");

      expect(documents.map((d) => d.id)).toEqual([insurance.id, contract.id, first.id, second.id]);
    },
  );
});
